"""Pagination helpers for the product listing."""


def page_count(total, per_page):
    """Return the number of pages needed to display `total` items with `per_page` items per page."""
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    if total <= 0:
        return 0
    # Ceiling division: (total + per_page - 1) // per_page
    return (total + per_page - 1) // per_page


def page_slice(items, page, per_page):
    """Return the slice of `items` that belongs on page `page` (1‑indexed) with `per_page` items per page."""
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    if page < 1:
        page = 1

    total = len(items)
    total_pages = page_count(total, per_page)

    # If page is beyond total pages, return last page
    if page > total_pages:
        page = total_pages

    start = (page - 1) * per_page
    end = start + per_page

    return items[start:end]

